export const MOSFET_LOSS_GROUPS={
 channel:{title:'Channel conduction',category:'conduction',pairs:[['Id','Vds'],['Id','Rds']],hint:'Vds–Id or Rds(on)–Id',use:'Used during gate-on conduction. Reverse gate-on current uses the symmetric channel magnitude approximation.',formula:'p(t) = Vds × |Id|',dependencies:['Tj','Vgs']},
 body:{title:'Body-diode conduction',category:'body',pairs:[['Id','Vsd']],hint:'Vsd–Id · gate-off reverse current',use:'Used when drain current is negative and the gate is off. Gate-on reverse current uses the channel model.',formula:'p(t) = Vsd × |Id|',dependencies:['Tj','Vgs']},
 on:{title:'Turn-on switching',category:'on',pairs:[['Id','Eon']],hint:'Eon–Id',use:'Energy is evaluated at each detected turn-on event and summed over the analysis window.',formula:'Pon = Σ Eon / window duration',dependencies:['Vds','Rg','Tj']},
 off:{title:'Turn-off switching',category:'off',pairs:[['Id','Eoff']],hint:'Eoff–Id',use:'Energy is evaluated at each detected turn-off event and summed over the analysis window.',formula:'Poff = Σ Eoff / window duration',dependencies:['Vds','Rg','Tj']},
 recovery:{title:'Reverse recovery',category:'recovery',pairs:[['If','Err'],['di_dt','Qrr']],hint:'Err–If or Qrr–di/dt',use:'Used at detected body-diode recovery events. Confirm that recovery energy is not already counted in Eon.',formula:'Prr = Σ Err / window duration',dependencies:['Tj']},
 temperature:{title:'Temperature correction',category:null,pairs:[['Tj','Rds_normalised']],hint:'Normalised Rds(on)–Tj',use:'Multiplies an absolute Rds model without its own Tj dependence. It is not applied to a Vds–Id model.',formula:'Rds(Tj) = Rds(reference) × ratio(Tj)',dependencies:['Vgs','Id']}
};
export function matchesAxes(curve,pair){return curve.xName===pair[0]&&curve.yName===pair[1]||curve.xName===pair[1]&&curve.yName===pair[0];}
export function groupCurves(candidate,key){const group=MOSFET_LOSS_GROUPS[key];return group?(candidate.curves||[]).filter(c=>group.pairs.some(pair=>matchesAxes(c,pair))):[];}
export function resolveMosfetCurve(candidate,key){const group=MOSFET_LOSS_GROUPS[key],choice=candidate.lossModels?.[key];if(!group)throw Error('Unknown MOSFET loss group');if(choice==='none'&&key==='temperature')return null;if(choice){const curve=groupCurves(candidate,key).find(c=>c.id===choice);if(!curve)throw Error(group.title+': selected characteristic is missing or incompatible; choose another curve');return curve;}for(const pair of group.pairs){const matches=groupCurves(candidate,key).filter(c=>matchesAxes(c,pair));if(matches.length>1)throw Error(group.title+': multiple matching characteristics; explicitly select the active curve');if(matches.length)return matches[0];}return null;}
export function lossGroupState(candidate,key){const group=MOSFET_LOSS_GROUPS[key],curves=groupCurves(candidate,key),enabled=group.category?candidate.enabled.includes(group.category):candidate.lossModels?.temperature!=='none'&&curves.length>0;let active=null,error=null;try{active=resolveMosfetCurve(candidate,key);}catch(e){error=e.message;}const issues=[];if(error)issues.push(error);
 if(active){const its=active.iterations||[];if(!its.length||its.some(it=>!Array.isArray(it.x)||!Array.isArray(it.y)||it.x.length<2||it.x.length!==it.y.length||![...it.x,...it.y].every(Number.isFinite)))issues.push('Each iteration needs at least two finite X/Y pairs.');const required=key==='recovery'&&[active.xName,active.yName].includes('Qrr')?['Tj','If']:group.dependencies;for(const k of required){if(its.some(it=>!Number.isFinite(it.deps?.[k])))issues.push('Missing numeric reference dependency: '+k);}const target={Tj:candidate.thermal?.temperature,Vgs:candidate.gateType==='logic'?(key==='body'?candidate.vgsOff:candidate.vgsOn):null,Rg:key==='on'?candidate.rgOn:key==='off'?candidate.rgOff:null};for(const [k,value] of Object.entries(target)){if(!required.includes(k)||(k==='Tj'&&['on','off'].includes(key)&&active.temperatureIndependent))continue;if(!Number.isFinite(value)){if(k==='Tj'||k==='Rg'||(k==='Vgs'&&candidate.gateType==='logic'))issues.push('Set the configured '+k+' value in Settings / Thermal.');continue;}const refs=its.map(it=>it.deps?.[k]).filter(Number.isFinite);if(refs.length&&(value<Math.min(...refs)||value>Math.max(...refs)))issues.push(`${k} requested ${value}; references ${Math.min(...refs)} … ${Math.max(...refs)}. Review fixed-reference / extrapolation behaviour.`);}if(active.temperatureIndependent&&new Set(its.map(it=>it.deps?.Tj)).size>1)issues.push('Temperature-independent energy requires one reference temperature.');}
 let applied=enabled;if(key==='temperature'){let channel;try{channel=resolveMosfetCurve(candidate,'channel');}catch{}applied=enabled&&candidate.enabled.includes('conduction')&&channel&&[channel.xName,channel.yName].includes('Rds');if(applied&&channel.iterations.some(it=>'Tj' in (it.deps||{})))issues.push('The active absolute Rds model already includes Tj. Disable this correction to avoid double correction.');}
 if(key==='recovery'&&enabled&&!candidate.recoveryConfirmed)issues.push('Confirm recovery is not already included in Eon.');
 const status=key==='temperature'&&!applied?'Optional / not used':!enabled?'Disabled':!active&&!error?'Missing curve':issues.length?'Needs review':'Ready';return {group,curves,active,enabled:!!enabled,applied:!!applied,issues,status};}
